   }
  ]
 },
 {
  "question": "The to-do list user guide was written into the change record because the author could not write to docs/, where this project keeps user guides. Where should it live?",
  "header": "Q-31",
  "multiSelect": false,
  "options": [
   {
    "label": "Move it to docs/ with the other guide (recommended)",
    "description": "It becomes docs/user-guide-todo-list.md with a row in docs/README.md, and the conventions name the person using a screen as a docs/ reader"
   },
   {
    "label": "Leave it in the change record",
    "description": "The guide stays as history of this change only, and the to-do list screen has no user guide under docs/"
   }
  ]
 }
]

